void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
   vec2 uv = ( fragCoord - .5* iResolution.xy ) /iResolution.y;
   vec3 col = vec3(0.);
   fragColor = vec4(col,1.0);

   float tt = iTime;

   vec3 camPos = vec3(tt, 3., 10.); 
   vec3 rayDir = normalize(vec3(uv, -1)); 
   float depth = 0.0;

   float closest;
   vec3 a1,b1,c1,a2,b2,c2;
   vec3 coord_a, coord_b, coord_c;
   vec3 coord_1a, coord_1b, coord_1c;
   vec3 coord_2a, coord_2b, coord_2c;

   vec3 p = camPos;

   // Raymarching Loop
   for(int numIter = 0; numIter < 90; numIter++){
     p = camPos + depth * rayDir;

     // Domain Repetition    
     float scale = 2.;
     vec2 cellID = round(scale * p.xz); 
     p.xz = (scale * p.xz) - cellID;

     // Noise Parameters
     float nf = .15;
     float amp = 4.0;

     // Neighbor Checking
     float nReach = 1.;
     float sx = sign(p.x);
     float sz = sign(p.z);             
     float minVal_1 = 1E20;
     float minVal_2 = 1E20;
     for(float i = 0.; i <= nReach; i++)
     for(float j = 0.; j <= nReach; j++){

       vec3 cV = vec3(i * sx,0.,j * sz);

       vec2 center = (cellID + cV.xz) / scale;

       float offC = .5 / scale;

       // Open Simplex Noise
       float ha1 = amp*simplex3d(vec3(nf*(center.x - offC), nf*(center.y - offC), 0.));
       float hb1 = amp*simplex3d(vec3(nf*(center.x - offC), nf*(center.y + offC), 0.));
       float hc1 = amp*simplex3d(vec3(nf*(center.x + offC), nf*(center.y + offC), 0.));

  //   Commenting out duplicate calls
  //     float ha2 = amp*simplex3d(vec3(nf*(center.x + .5), nf*(center.y + .5), 0.));
       float hb2 = amp*simplex3d(vec3(nf*(center.x + offC), nf*(center.y - offC), 0.));
  //     float hc2 = amp*simplex3d(vec3(nf*(center.x - .5), nf*(center.y - .5), 0.));

       // Triangle Points (Black)
       a1 = vec3(-offC * scale,ha1,-offC * scale);
       b1 = vec3(-offC * scale,hb1,+offC * scale);
       c1 = vec3(+offC * scale,hc1,+offC * scale);

       // Triangle Points (White)
       a2 = c1;
       b2 = vec3(+offC * scale,hb2,-offC * scale);
       c2 = a1;

       // Calculate the SDFs (2x triangles per "quad")
       float t1_SDF = udTriangle(p - cV, a1, b1, c1);
       float t2_SDF = udTriangle(p - cV, a2, b2, c2);

       // Get the minimums
       if (t1_SDF < minVal_1){
         minVal_1 = t1_SDF;
         coord_1a = a1;
         coord_1b = b1;
         coord_1c = c1;

       }

       if (t2_SDF < minVal_2){
         minVal_2 = t2_SDF;
         coord_2a = a2;
         coord_2b = b2;
         coord_2c = c2;
       }


     } // End Neigbor Checking

     // Which of the 2x triangles are we closer to?
     float d;
     if(minVal_1 <= minVal_2){
       coord_a = coord_1a;
       coord_b = coord_1b;
       coord_c = coord_1c;
     }
     else{
       coord_a = coord_2a;
       coord_b = coord_2b;
       coord_c = coord_2c;
     }

     d = min(minVal_1, minVal_2);

     // Not sure why I had to decrease the march step by 60% here,
     // but it got rid of artifacts.  Maybe I was overstepping?
     depth += d * .4;
     if (d < .01 || depth > 25.0) break;
   }

   if(depth > 25.){
     // Draw Stars
     vec2 uvStars = uv * 30.;
     vec2 starCell = floor(uvStars);
     uvStars = fract(uvStars) - .5;   
     float minStar = 1E20;
     for(float i=-1.;i<=1.;i++)
     for(float j=-1.;j<=1.;j++){
       float r1 = fract(sin(dot(starCell + vec2(i,j), vec2(3.0,12.0)))*15745.7342) * 2. - 1.;
       float r2 = fract(sin(dot(starCell + vec2(i,j), vec2(7.0,43.0)))*13131.8234) * 2. - 1.;
       float spark = 0.;
       if (r2 > .3) spark = .1 * sin(TAU*(tt/4. + r1));     
       float ssize = r2 * .1;  
       float star = length((uvStars - vec2(i,j)) - 1.*vec2(r1,r2)) - ssize+spark;
       minStar = min(minStar, star);
     }
     float w = 54./iResolution.y;
     col += smoothstep(w,-w,minStar);

     // Draw Moon
     float m = length(uv-vec2(.2,-.1)) - .4;
     w = 1./iResolution.y;
     col += smoothstep(w,-w,m); 
   }
   else{
     // Barycentric Coordinates
     float u = length(cross(coord_a - coord_c, p - coord_c)) / 2.;
     float v = length(cross(coord_c - coord_b, p - coord_b)) / 2.;
     float w = length(cross(coord_b - coord_a, p - coord_a)) / 2.;

     // Don't show "quad" diagonal.
     if( abs(v) <= .04 || abs(w) < .04) // || abs(w) < .03){ 
      col = vec3(1.);

     else col = vec3(0.);

     // Depth based fog effect, thanks SnoopethDuckDuck!
     col = mix(col, vec3(0.), smoothstep(7., 25., depth));
   }

   fragColor = vec4(col,1.0);

}

#define rotation(angle) mat2(cos(angle), -sin(angle), sin(angle), cos(angle));

float PI = 3.14159;
float TAU = 2.*3.14159;

float dot2( in vec3 v ) { return dot(v,v); }

// Thanks IQ!
float udTriangle( vec3 p, vec3 a, vec3 b, vec3 c )
{
  vec3 ba = b - a; vec3 pa = p - a;
  vec3 cb = c - b; vec3 pb = p - b;
  vec3 ac = a - c; vec3 pc = p - c;
  vec3 nor = cross( ba, ac );

  return sqrt(
    (sign(dot(cross(ba,nor),pa)) +
     sign(dot(cross(cb,nor),pb)) +
     sign(dot(cross(ac,nor),pc))<2.0)
     ?
     min( min(
     dot2(ba*clamp(dot(ba,pa)/dot2(ba),0.0,1.0)-pa),
     dot2(cb*clamp(dot(cb,pb)/dot2(cb),0.0,1.0)-pb) ),
     dot2(ac*clamp(dot(ac,pc)/dot2(ac),0.0,1.0)-pc) )
     :
     dot(nor,pa)*dot(nor,pa)/dot2(nor) );
}

// 3d simplex noise from https://www.shadertoy.com/view/XsX3zB

vec3 random3(vec3 c) {
	float j = 4096.0*sin(dot(c,vec3(17.0, 59.4, 15.0)));
	vec3 r;
	r.z = fract(512.0*j);
	j *= .125;
	r.x = fract(512.0*j);
	j *= .125;
	r.y = fract(512.0*j);
	return r-0.5;
}

/* skew constants for 3d simplex functions */
const float F3 =  0.3333333;
const float G3 =  0.1666667;

/* 3d simplex noise */
float simplex3d(vec3 p) {
	 /* 1. find current tetrahedron T and it's four vertices */
	 /* s, s+i1, s+i2, s+1.0 - absolute skewed (integer) coordinates of T vertices */
	 /* x, x1, x2, x3 - unskewed coordinates of p relative to each of T vertices*/

	 /* calculate s and x */
	 vec3 s = floor(p + dot(p, vec3(F3)));
	 vec3 x = p - s + dot(s, vec3(G3));

	 /* calculate i1 and i2 */
	 vec3 e = step(vec3(0.0), x - x.yzx);
	 vec3 i1 = e*(1.0 - e.zxy);
	 vec3 i2 = 1.0 - e.zxy*(1.0 - e);

	 /* x1, x2, x3 */
	 vec3 x1 = x - i1 + G3;
	 vec3 x2 = x - i2 + 2.0*G3;
	 vec3 x3 = x - 1.0 + 3.0*G3;

	 /* 2. find four surflets and store them in d */
	 vec4 w, d;

	 /* calculate surflet weights */
	 w.x = dot(x, x);
	 w.y = dot(x1, x1);
	 w.z = dot(x2, x2);
	 w.w = dot(x3, x3);

	 /* w fades from 0.6 at the center of the surflet to 0.0 at the margin */
	 w = max(0.6 - w, 0.0);

	 /* calculate surflet components */
	 d.x = dot(random3(s), x);
	 d.y = dot(random3(s + i1), x1);
	 d.z = dot(random3(s + i2), x2);
	 d.w = dot(random3(s + 1.0), x3);

	 /* multiply d by w^4 */
	 w *= w;
	 w *= w;
	 d *= w;

	 /* 3. return the sum of the four surflets */
	 return dot(d, vec4(52.0));
}
